changeSet.sql:
---------------------------------------------------- -- 1. Drop existing foreign keys referencing trades ----------------------------------------------------
ALTER TABLE settlements DROP CONSTRAINT IF EXISTS fk_settlements_trade;
---------------------------------------------------- -- 2. Rename old table ----------------------------------------------------
ALTER TABLE trades RENAME TO trades_legacy;
---------------------------------------------------- -- 3. Create partitioned trades table ----------------------------------------------------
CREATE TABLE trades (
id BIGSERIAL NOT NULL,
trade_ref VARCHAR(30) NOT NULL,
instrument_id BIGINT NOT NULL,
counterparty_id BIGINT NOT NULL,
asset_class VARCHAR(20) NOT NULL,
side VARCHAR(4) NOT NULL,
quantity NUMERIC(18,4) NOT NULL,
price NUMERIC(18,4) NOT NULL,
trade_date DATE NOT NULL,
status VARCHAR(20) NOT NULL DEFAULT 'PENDING',
deleted_at TIMESTAMPTZ,
created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
modified_at TIMESTAMPTZ,
CONSTRAINT pk_trades PRIMARY KEY (id, trade_date),
CONSTRAINT fk_trade_instrument FOREIGN KEY (instrument_id) REFERENCES instruments(id),
CONSTRAINT fk_trade_counterparty FOREIGN KEY (counterparty_id) REFERENCES counterparties(id)
) PARTITION BY RANGE(trade_date);
---------------------------------------------------- -- 4. Create partitions ----------------------------------------------------
CREATE TABLE trades_y2026m04 PARTITION OF trades FOR VALUES FROM ('2026-04-01') TO ('2026-05-01');
CREATE TABLE trades_y2026m05 PARTITION OF trades FOR VALUES FROM ('2026-05-01') TO ('2026-06-01');
CREATE TABLE trades_y2026m06 PARTITION OF trades FOR VALUES FROM ('2026-06-01') TO ('2026-07-01');
CREATE TABLE trades_y2026m07 PARTITION OF trades FOR VALUES FROM ('2026-07-01') TO ('2026-08-01');
CREATE TABLE trades_default PARTITION OF trades DEFAULT;
---------------------------------------------------- -- 5. Copy data ----------------------------------------------------
INSERT INTO trades ( id, trade_ref, instrument_id, counterparty_id, asset_class, side, quantity, price, trade_date, status, deleted_at, created_at, modified_at ) SELECT id, trade_ref, instrument_id, counterparty_id, asset_class, side, quantity, price, trade_date, status, deleted_at, created_at, modified_at FROM trades_legacy;
---------------------------------------------------- -- 6. Remove old table ----------------------------------------------------
DROP TABLE trades_legacy CASCADE;
---------------------------------------------------- -- 7. Indexes ----------------------------------------------------
CREATE INDEX idx_trades_status ON trades(status);
CREATE INDEX idx_trades_instrument ON trades(instrument_id);
CREATE INDEX idx_trades_counterparty ON trades(counterparty_id);
---------------------------------------------------- -- 8. Recreate FK correctly ----------------------------------------------------
ALTER TABLE settlements ADD COLUMN IF NOT EXISTS trade_date DATE;
UPDATE settlements s SET trade_date = ( SELECT t.trade_date FROM trades t WHERE t.id = s.trade_id LIMIT 1 );
ALTER TABLE settlements ADD CONSTRAINT fk_settlements_trade FOREIGN KEY (trade_id, trade_date) REFERENCES trades(id, trade_date);
